<?php
declare(strict_types=1); function mg_personal_workflows_create_data_request(PDO $pdo, int $userId, array $input): array { mg_personal_workflows_require_schema($pdo); $context=mg_personal_agent_resolve_context($pdo,$userId,(string)($input['context_type'] ?? 'linked_user'),(string)($input['context_id'] ?? '')); if(($context['type'] ?? '')!=='linked_user') throw new InvalidArgumentException('Choose a mutually connected Microgifter user.'); $subjectId=(int)($context['internal']['contact_user_id'] ?? 0); if($subjectId<1) throw new RuntimeException('Linked contact not found.'); $eligibility=mg_user_contact_list_eligibility_detail($pdo,$userId,$subjectId); if(empty($eligibility['eligible'])) throw new RuntimeException('The recipient is no longer eligible for a profile-data request.'); $preference=$pdo->prepare('SELECT allow_profile_import_requests FROM user_contact_preferences WHERE user_id=? LIMIT 1'); $preference->execute([$subjectId]); $allowed=$preference->fetchColumn(); if($allowed!==false && (int)$allowed!==1) throw new RuntimeException('This user does not allow profile-data requests.'); $scopes=mg_personal_workflows_request_scopes($input['scopes'] ?? []); if($scopes===[]) throw new InvalidArgumentException('Choose at least one permission scope.'); $type=in_array('profile.address',$scopes,true) ? (in_array('profile.gift_preferences',$scopes,true)||in_array('profile.birthdate',$scopes,true)?'mixed':'address') : 'preferences'; $message=mg_personal_agent_nullable_text($input['message'] ?? null,1000); if($message!==null && mg_personal_workflows_sensitive_text($message)) throw new InvalidArgumentException('Request messages cannot contain credentials or payment details.'); $existing=$pdo->prepare("SELECT public_id FROM user_recipient_data_requests WHERE requester_user_id=? AND subject_user_id=? AND status='pending' LIMIT 1"); $existing->execute([$userId,$subjectId]); if($existingId=$existing->fetchColumn()) throw new RuntimeException('A profile-data request is already pending for this user.'); $publicId=mg_public_uuid(); $expires=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->modify('+30 days')->format('Y-m-d H:i:s'); $pdo->prepare("INSERT INTO user_recipient_data_requests
        (public_id,requester_user_id,subject_user_id,request_type,requested_scopes_json,message,status,expires_at,created_at,updated_at)
        VALUES (?,?,?,?,?,?,'pending',?,NOW(),NOW())") ->execute([$publicId,$userId,$subjectId,$type,mg_personal_agent_json_encode($scopes),$message,$expires]); $requesterName=mg_personal_workflows_user_label($pdo,$userId); mg_personal_workflows_notify($pdo,$subjectId,'recipient_data_request','Gifting information request',$requesterName.' requested permission to use selected gifting information.','/agent.php?view=requests&request='.rawurlencode($publicId)); mg_audit('user_recipient_data_request.created','user_recipient_data_request',['request_id'=>$publicId,'subject_user_id'=>$subjectId,'scopes'=>$scopes],$userId); foreach(mg_personal_workflows_requests($pdo,$userId)['outgoing'] as $request) if($request['id']===$publicId) return $request; throw new RuntimeException('Unable to load recipient data request.'); } function mg_personal_workflows_import_contact(PDO $pdo, int $requesterId, int $subjectId): array { $stmt=$pdo->prepare('SELECT id,public_id FROM user_contacts WHERE owner_user_id=? AND linked_user_id=? LIMIT 1'); $stmt->execute([$requesterId,$subjectId]); $row=$stmt->fetch(PDO::FETCH_ASSOC); if($row) return ['id'=>(int)$row['id'],'public_id'=>(string)$row['public_id']]; $name=mg_personal_workflows_user_label($pdo,$subjectId); $publicId=mg_public_uuid(); $pdo->prepare("INSERT INTO user_contacts
        (public_id,owner_user_id,linked_user_id,display_name,source,source_user_id,profile_imported_at,profile_data_version,created_at,updated_at)
        VALUES (?,?,?,?,'profile_import',?,NOW(),?,NOW(),NOW())") ->execute([$publicId,$requesterId,$subjectId,$name,$subjectId,hash('sha256',$subjectId.'|'.microtime(true))]); return ['id'=>(int)$pdo->lastInsertId(),'public_id'=>$publicId]; } function mg_personal_workflows_scope_fields(string $scope): array { return match($scope) { 'profile.gift_preferences'=>['gift_preferences','interests','allergies_or_restrictions','preferred_merchants','preferred_categories','budget_min','budget_max'], 'profile.address'=>['address_line_1','address_line_2','city','state_region','postal_code','country_code'], 'profile.birthdate'=>['birthdate','birth_year_visible'], default=>[], }; } function mg_personal_workflows_clean_response_scope(string $scope, array $input): array { if($scope==='profile.gift_preferences') { $data=[ 'gift_preferences'=>mg_personal_agent_nullable_text($input['gift_preferences'] ?? null,10000), 'interests'=>mg_personal_agent_nullable_text($input['interests'] ?? null,10000), 'allergies_or_restrictions'=>mg_personal_agent_nullable_text($input['allergies_or_restrictions'] ?? null,10000), 'preferred_merchants'=>mg_personal_agent_nullable_text($input['preferred_merchants'] ?? null,10000), 'preferred_categories'=>mg_personal_agent_nullable_text($input['preferred_categories'] ?? null,10000), 'budget_min'=>mg_personal_agent_decimal($input['budget_min'] ?? null), 'budget_max'=>mg_personal_agent_decimal($input['budget_max'] ?? null), ]; if($data['budget_min']!==null && $data['budget_max']!==null && $data['budget_min']>$data['budget_max']) throw new InvalidArgumentException('Minimum budget cannot exceed maximum budget.'); if(count(array_filter($data,static fn(mixed $value):bool=>$value!==null && $value!==''))===0) throw new InvalidArgumentException('Add at least one gifting preference before approving that scope.'); return $data; } if($scope==='profile.address') { $data=[ 'address_line_1'=>mg_personal_agent_nullable_text($input['address_line_1'] ?? null,190), 'address_line_2'=>mg_personal_agent_nullable_text($input['address_line_2'] ?? null,190), 'city'=>mg_personal_agent_nullable_text($input['city'] ?? null,120), 'state_region'=>mg_personal_agent_nullable_text($input['state_region'] ?? null,120), 'postal_code'=>mg_personal_agent_nullable_text($input['postal_code'] ?? null,40), 'country_code'=>strtoupper((string)(mg_personal_agent_nullable_text($input['country_code'] ?? 'US',2) ?? 'US')), ]; if($data['address_line_1']===null || $data['city']===null || $data['state_region']===null || $data['postal_code']===null) { throw new InvalidArgumentException('Address approval requires street, city, state/region, and postal code.'); } return $data; } if($scope==='profile.birthdate') { $birthdate=mg_personal_agent_date($input['birthdate'] ?? null); if($birthdate===null || strtotime($birthdate)>time()) throw new InvalidArgumentException('Enter a valid birthday.'); return ['birthdate'=>$birthdate,'birth_year_visible'=>mg_personal_workflows_bool($input['birth_year_visible'] ?? false)?1:0]; } throw new InvalidArgumentException('Unsupported recipient-data scope.'); } function mg_personal_workflows_respond_data_request(PDO $pdo, int $subjectUserId, string $publicId, string $decision, array $input): array { mg_personal_workflows_require_schema($pdo); if(!in_array($decision,['approve','decline'],true)) throw new InvalidArgumentException('Choose approve or decline.'); $pdo->beginTransaction(); try { $stmt=$pdo->prepare("SELECT * FROM user_recipient_data_requests WHERE subject_user_id=? AND public_id=? LIMIT 1 FOR UPDATE"); $stmt->execute([$subjectUserId,$publicId]); $request=$stmt->fetch(PDO::FETCH_ASSOC); if(!$request) throw new RuntimeException('Recipient data request not found.'); if((string)$request['status']!=='pending') throw new RuntimeException('This request has already been resolved.'); if(!empty($request['expires_at']) && strtotime((string)$request['expires_at'])<time()) { $pdo->prepare("UPDATE user_recipient_data_requests SET status='expired',updated_at=NOW() WHERE id=?")->execute([(int)$request['id']]); throw new RuntimeException('This request has expired.'); } $responseNote=mg_personal_agent_nullable_text($input['response_note'] ?? null,1000); if($decision==='decline') { $pdo->prepare("UPDATE user_recipient_data_requests SET status='declined',approved_scopes_json=NULL,response_note=?,responded_at=NOW(),updated_at=NOW() WHERE id=?") ->execute([$responseNote,(int)$request['id']]); mg_personal_workflows_notify($pdo,(int)$request['requester_user_id'],'recipient_data_request_declined','Gifting information request declined','The recipient declined the request.','/agent.php?view=requests'); $pdo->commit(); mg_audit('user_recipient_data_request.declined','user_recipient_data_request',['request_id'=>$publicId],$subjectUserId); return ['id'=>$publicId,'status'=>'declined','approved_scopes'=>[]]; } $requested=mg_personal_workflows_request_scopes(mg_personal_agent_json($request['requested_scopes_json'])); $approved=mg_personal_workflows_request_scopes($input['approved_scopes'] ?? []); $approved=array_values(array_intersect($requested,$approved)); if($approved===[]) throw new InvalidArgumentException('Approve at least one requested scope or decline the request.'); $contact=mg_personal_workflows_import_contact($pdo,(int)$request['requester_user_id'],$subjectUserId); $fieldValues=[];$fieldScopes=[]; foreach($approved as $scope) { $scopeData=mg_personal_workflows_clean_response_scope($scope,$input); foreach($scopeData as $field=>$value) { $fieldValues[$field]=$value; $fieldScopes[$field]=$scope; } $permissionPublicId=mg_public_uuid(); $pdo->prepare("INSERT INTO user_contact_profile_permissions
                (public_id,subject_user_id,grantee_user_id,permission_scope,status,granted_at,created_at,updated_at)
                VALUES (?,?,?,?,'granted',NOW(),NOW(),NOW())
                ON DUPLICATE KEY UPDATE status='granted',granted_at=NOW(),revoked_at=NULL,expires_at=NULL,updated_at=NOW()") ->execute([$permissionPublicId,$subjectUserId,(int)$request['requester_user_id'],$scope]); } $set=[];$params=[]; foreach($fieldValues as $field=>$value) { if(!in_array($field,['gift_preferences','interests','allergies_or_restrictions','preferred_merchants','preferred_categories','budget_min','budget_max','address_line_1','address_line_2','city','state_region','postal_code','country_code','birthdate','birth_year_visible'],true)) continue; $set[]=$field.'=?';$params[]=$value; } $version=hash('sha256',$subjectUserId.'|'.mg_personal_agent_json_encode($approved).'|'.mg_personal_agent_json_encode($fieldValues)); $set[]="source='profile_import'";$set[]='source_user_id=?';$params[]=$subjectUserId;$set[]='profile_imported_at=NOW()';$set[]='profile_data_version=?';$params[]=$version;$set[]='updated_at=NOW()'; $params[]=(int)$contact['id'];$params[]=(int)$request['requester_user_id']; $pdo->prepare('UPDATE user_contacts SET '.implode(',',$set).' WHERE id=? AND owner_user_id=?')->execute($params); $importPublicId=mg_public_uuid(); $pdo->prepare("INSERT INTO user_contact_profile_imports
            (public_id,owner_user_id,subject_user_id,user_contact_id,imported_scopes_json,profile_data_version,status,imported_at,updated_at)
            VALUES (?,?,?,?,?,?,'active',NOW(),NOW())") ->execute([$importPublicId,(int)$request['requester_user_id'],$subjectUserId,(int)$contact['id'],mg_personal_agent_json_encode($approved),$version]); $importId=(int)$pdo->lastInsertId(); foreach($fieldValues as $field=>$value) { $hash=mg_personal_workflows_value_hash($value,$field); $pdo->prepare("INSERT INTO user_contact_profile_import_fields
                (import_id,owner_user_id,subject_user_id,permission_scope,field_name,value_hash,status,imported_at,updated_at)
                VALUES (?,?,?,?,?,?,'active',NOW(),NOW())") ->execute([$importId,(int)$request['requester_user_id'],$subjectUserId,$fieldScopes[$field],$field,$hash]); } $status=count($approved)===count($requested)?'approved':'partially_approved'; $pdo->prepare("UPDATE user_recipient_data_requests SET imported_contact_id=?,approved_scopes_json=?,status=?,response_note=?,responded_at=NOW(),updated_at=NOW() WHERE id=?") ->execute([(int)$contact['id'],mg_personal_agent_json_encode($approved),$status,$responseNote,(int)$request['id']]); mg_personal_workflows_notify($pdo,(int)$request['requester_user_id'],'recipient_data_request_approved','Gifting information shared','The recipient approved selected gifting information.','/agent.php?view=requests'); $pdo->commit(); mg_audit('user_recipient_data_request.approved','user_recipient_data_request',['request_id'=>$publicId,'status'=>$status,'approved_scopes'=>$approved,'contact_id'=>$contact['public_id']],$subjectUserId); return ['id'=>$publicId,'status'=>$status,'approved_scopes'=>$approved,'contact_id'=>$contact['public_id']]; } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; } } function mg_personal_workflows_cancel_data_request(PDO $pdo, int $requesterId, string $publicId): array { $stmt=$pdo->prepare("UPDATE user_recipient_data_requests SET status='cancelled',updated_at=NOW() WHERE requester_user_id=? AND public_id=? AND status='pending'"); $stmt->execute([$requesterId,$publicId]); if($stmt->rowCount()!==1) throw new RuntimeException('Pending recipient data request not found.'); mg_audit('user_recipient_data_request.cancelled','user_recipient_data_request',['request_id'=>$publicId],$requesterId); return ['id'=>$publicId,'status'=>'cancelled']; } function mg_personal_workflows_revoke_data_request(PDO $pdo, int $subjectUserId, string $publicId): array { $allowedFields=['gift_preferences','interests','allergies_or_restrictions','preferred_merchants','preferred_categories','budget_min','budget_max','address_line_1','address_line_2','city','state_region','postal_code','country_code','birthdate','birth_year_visible']; $pdo->beginTransaction(); try { $stmt=$pdo->prepare("SELECT * FROM user_recipient_data_requests WHERE subject_user_id=? AND public_id=? AND status IN ('approved','partially_approved') LIMIT 1 FOR UPDATE"); $stmt->execute([$subjectUserId,$publicId]); $request=$stmt->fetch(PDO::FETCH_ASSOC); if(!$request) throw new RuntimeException('Approved recipient data request not found.'); $approved=mg_personal_workflows_request_scopes(mg_personal_agent_json($request['approved_scopes_json'] ?? null)); foreach($approved as $scope) { $pdo->prepare("UPDATE user_contact_profile_permissions SET status='revoked',revoked_at=NOW(),updated_at=NOW() WHERE subject_user_id=? AND grantee_user_id=? AND permission_scope=?") ->execute([$subjectUserId,(int)$request['requester_user_id'],$scope]); } $imports=$pdo->prepare("SELECT id,user_contact_id FROM user_contact_profile_imports WHERE owner_user_id=? AND subject_user_id=? AND status='active' FOR UPDATE"); $imports->execute([(int)$request['requester_user_id'],$subjectUserId]); foreach($imports->fetchAll(PDO::FETCH_ASSOC) as $import) { $fields=$pdo->prepare("SELECT id,field_name,value_hash FROM user_contact_profile_import_fields WHERE import_id=? AND status='active'"); $fields->execute([(int)$import['id']]); foreach($fields->fetchAll(PDO::FETCH_ASSOC) as $field) { $name=(string)$field['field_name']; if(!in_array($name,$allowedFields,true)) continue; $valueStmt=$pdo->prepare('SELECT '.$name.' FROM user_contacts WHERE id=? AND owner_user_id=? LIMIT 1'); $valueStmt->execute([(int)$import['user_contact_id'],(int)$request['requester_user_id']]); $current=$valueStmt->fetchColumn(); $currentHash=mg_personal_workflows_value_hash($current,$name); if(hash_equals((string)$field['value_hash'],$currentHash)) { $pdo->prepare('UPDATE user_contacts SET '.$name.'=NULL,updated_at=NOW() WHERE id=? AND owner_user_id=?') ->execute([(int)$import['user_contact_id'],(int)$request['requester_user_id']]); } $pdo->prepare("UPDATE user_contact_profile_import_fields SET status='revoked',revoked_at=NOW(),updated_at=NOW() WHERE id=?") ->execute([(int)$field['id']]); } $pdo->prepare("UPDATE user_contact_profile_imports SET status='revoked',revoked_at=NOW(),updated_at=NOW() WHERE id=?")->execute([(int)$import['id']]); } $pdo->prepare("UPDATE user_recipient_data_requests SET status='revoked',revoked_at=NOW(),updated_at=NOW() WHERE id=?")->execute([(int)$request['id']]); mg_personal_workflows_notify($pdo,(int)$request['requester_user_id'],'recipient_data_request_revoked','Gifting information permission revoked','Previously shared profile information is no longer available to the Personal Gifting Agent.','/agent.php?view=requests'); $pdo->commit(); mg_audit('user_recipient_data_request.revoked','user_recipient_data_request',['request_id'=>$publicId,'revoked_scopes'=>$approved],$subjectUserId); return ['id'=>$publicId,'status'=>'revoked','revoked_scopes'=>$approved]; } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; } } 